def max_min_dist_limited_optimized(M, S):
    max_d = 0
    for k in range(40, M + 1):
        for num_k_plus_1 in range(0, 50):
            for total_n in range(S // k, S // k + 30):
                num_k = total_n - num_k_plus_1
                if num_k < 0: continue
                seq = [k] * num_k + [k+1] * num_k_plus_1
                total_sum = sum(seq)
                if total_sum < S: continue
                if k+1 > M: continue

                # Subset sums using bitset
                sums = 1
                for x in seq:
                    sums |= (sums << x)

                # Find min_dist
                # We need to check bits around S
                min_d = 1000
                # Check bits from S-100 to S+100
                for i in range(max(0, S-100), S+101):
                    if (sums >> i) & 1:
                        min_d = min(min_d, abs(i - S))

                if min_d > max_d:
                    max_d = min_d
    return max_d

print(f"M=100, S=1810: {max_min_dist_limited_optimized(100, 1810)}")

