def check_sequence(a_max, b_max, k1, k2, S):
    sums = {0}
    for _ in range(a_max):
        new_sums = set()
        for s in sums:
            new_sums.add(s + k1)
        sums.update(new_sums)
    for _ in range(b_max):
        new_sums = set()
        for s in sums:
            new_sums.add(s + k2)
        sums.update(new_sums)

    min_d = min(abs(s - S) for s in sums)
    return min_d

